\title{The Variance of Rademacher Random Multiplicative Functions in Short Intervals}
\author{Aristotle}
\date{2026-07-09}

\begin{document}
\maketitle

\begin{abstract}
We study the fluctuations of partial sums of a \emph{Rademacher random multiplicative function} $f$ --- the arithmetic function obtained by assigning an independent random sign $\varepsilon_p = \pm 1$ to each prime $p$, setting $f(n) = \prod_{p \mid n} \varepsilon_p$ for squarefree $n$, and $f(n) = 0$ otherwise. Our central contribution is an \emph{exact, unconditional identity} for the variance of these partial sums over an arbitrary finite index set: the variance equals the number of squarefree integers in that set. Specialized to a short interval $[x, x+y]$, this pins down the normalizing constant $\sigma(x,y)^2 = \#\{n \in [x,x+y] : n \text{ squarefree}\}$ that governs any central limit theorem in this regime. We derive the identity from a clean orthogonality relation for the second mixed moments of $f$, and we complement it with a companion computation of the variance of the squarefree indicator under the uniform distribution on $\{1, \dots, N\}$, which reduces --- via the idempotency of the indicator --- to a Bernoulli variance $q_N(1 - q_N)$. Combining the variance identity with the classical squarefree-density asymptotic $(6/\pi^2)y + o(y)$ yields $\sigma(x,y)^2 \sim (6/\pi^2)y$, isolating the number-theoretic content of the short-interval central limit theorem from its probabilistic content. We state the conjectural Gaussian limit, describe the finite probability model that makes all moment computations elementary and rigorous, provide algorithms and numerical demonstrations, and outline the moment-method route to full Gaussianity.
\end{abstract}

\noindent\textbf{Keywords:} Rademacher random multiplicative function, squarefree integers, variance, second moment, short intervals, central limit theorem, orthogonality, Euler product, method of moments.

\section{Introduction}

\subsection{Random multiplicative functions}
A \emph{multiplicative function} $g \colon \N \to \mathbb{C}$ satisfies $g(mn) = g(m)g(n)$ whenever $\gcd(m,n) = 1$. Such functions are the fundamental objects of multiplicative number theory; the M\"obius function $\mu$ and Dirichlet characters are archetypes. Their partial sums exhibit rich cancellation that is notoriously difficult to quantify, because the values $g(n)$ are governed by the prime factorization of $n$ and are therefore strongly, and multiplicatively, correlated.

To gain traction, one introduces \emph{random} multiplicative functions as probabilistic surrogates. Two models dominate the literature. In the \emph{Steinhaus} model each prime $p$ receives an independent value $z_p$ drawn uniformly from the unit circle $\{|z| = 1\}$. In the \emph{Rademacher} model each prime $p$ receives an independent uniform sign $\varepsilon_p \in \{+1, -1\}$, and $f$ is the multiplicative extension supported on squarefree integers. This paper concerns the Rademacher model, whose support on squarefree integers introduces the squarefree density $6/\pi^2$ into every quantitative statement.

\subsection{The short-interval problem}
Let $x$ be large and let $y = y(x)$ satisfy $y \to \infty$ and $y = o(x)$. Consider the partial sum over the short interval
\[
S(x,y) = \sum_{x \le n \le x+y} f(n).
\]
Because $\E[f(n)] = 0$ for every $n > 1$, the sum $S(x,y)$ is centered, and its typical size is measured by $\sigma(x,y) = \sqrt{\Var(S(x,y))}$. The central object of study is the \emph{normalized} sum $S(x,y)/\sigma(x,y)$, and the guiding question is whether it converges in distribution to a standard Gaussian $N(0,1)$ as $x \to \infty$. For the Steinhaus model, such a short-interval central limit theorem is known to hold across the full range $y \to \infty$, $y = o(x)$, with normalization essentially $\sigma(x,y)^2 = y$. It is natural to conjecture the Rademacher analogue, and the first step is to determine $\sigma(x,y)$ \emph{exactly}.

\subsection{Contributions}
\begin{enumerate}
\item \textbf{Exact variance identity} (Theorem~\ref{thm:var}): for any finite $A \subseteq \N$, $\Var(\sum_{n \in A} f(n)) = \#\{n \in A : n \text{ squarefree}\}$.
\item \textbf{Orthogonality of second moments} (Theorem~\ref{thm:orth}): $\E[f(m)f(n)] = \delta_{m,n}\,\one[m \text{ squarefree}]$.
\item \textbf{Interval specialization} (Corollary~\ref{cor:interval}): $\sigma(x,y)^2 = \#\{n \in [x,x+y] : n \text{ squarefree}\}$.
\item \textbf{Squarefree-indicator variance} (Theorem~\ref{thm:chi}): under the uniform law on $\{1,\dots,N\}$, $\Var_N(\chi) = q_N(1-q_N)$.
\item \textbf{Asymptotic normalization} (Corollary~\ref{cor:norm}): $\sigma(x,y)^2 \sim (6/\pi^2)y$.
\item \textbf{Conjectural CLT} (Conjecture~\ref{conj:clt}) and its moment-method roadmap.
\end{enumerate}
All moment computations are carried out in an explicit \emph{finite} probability model (Section~\ref{sec:model}), so Theorems~\ref{thm:var}, \ref{thm:orth}, and~\ref{thm:chi} are elementary and unconditional.

\section{The finite probability model}\label{sec:model}
Fix a finite set $P$ of prime numbers. The sample space is the set of sign patterns $\Omega_P = \{-1,+1\}^P$, equipped with the uniform probability measure assigning mass $2^{-|P|}$ to each pattern $\omega = (\varepsilon_p)_{p \in P}$. Expectation is the average $\E[X] = 2^{-|P|}\sum_{\omega \in \Omega_P} X(\omega)$.

\begin{definition}[Rademacher random multiplicative function]
For a sign pattern $\omega = (\varepsilon_p)_{p \in P}$, define, for every integer $n \ge 1$ all of whose prime factors lie in $P$,
\[
f(n) = \begin{cases} \prod_{p \mid n} \varepsilon_p, & n \text{ squarefree},\\ 0, & n \text{ not squarefree}. \end{cases}
\]
For a finite index set $A$, take $P$ to contain all prime factors of all elements of $A$; the resulting moments do not depend on the choice of such $P$.
\end{definition}

\begin{lemma}[Faithfulness on primes]
For $p \in P$, $f(p) = \varepsilon_p$.
\end{lemma}
\begin{proof}
A prime $p$ is squarefree and its only prime divisor is $p$, so the defining product has the single factor $\varepsilon_p$.
\end{proof}

\begin{lemma}[Sign symmetry]\label{lem:sym}
For any single prime $q$, replacing $\varepsilon_q$ by $-\varepsilon_q$ is a measure-preserving involution of $\Omega_P$. If $q \mid n$ and $n$ is squarefree, this involution sends $f(n) \mapsto -f(n)$.
\end{lemma}
\begin{proof}
Flipping one coordinate is a bijection of $\Omega_P$ preserving the uniform measure. If the squarefree $n$ is divisible by $q$, exactly one factor of $\prod_{p \mid n}\varepsilon_p$ changes sign.
\end{proof}

\section{The exact variance identity}

\begin{lemma}[Mean zero]\label{lem:mean}
For every $n > 1$, $\E[f(n)] = 0$; consequently $\E[\sum_{n\in A} f(n)] = 0$ for any finite $A \subseteq \{2,3,4,\dots\}$.
\end{lemma}
\begin{proof}
If $n$ is not squarefree, $f(n) \equiv 0$. If $n > 1$ is squarefree, pick a prime $q \mid n$; by Lemma~\ref{lem:sym} the involution flipping $\varepsilon_q$ negates $f(n)$ while preserving the measure, so $\E[f(n)] = -\E[f(n)]$, forcing $\E[f(n)] = 0$. Linearity extends this to the sum.
\end{proof}

\begin{theorem}[Orthogonality relation]\label{thm:orth}
For all $m,n \in \N$,
\[
\E[f(m)\,f(n)] = \begin{cases} 1, & m = n \text{ and } m \text{ squarefree},\\ 0, & \text{otherwise.} \end{cases}
\]
\end{theorem}
\begin{proof}
If either $m$ or $n$ is non-squarefree, the corresponding factor vanishes identically. Assume both squarefree. Grouping $f(m)f(n) = \prod_{p\mid m}\varepsilon_p \prod_{p\mid n}\varepsilon_p$ by prime, a prime dividing both contributes $\varepsilon_p^2 = 1$, while a prime dividing exactly one contributes a lone $\varepsilon_p$. If $m \ne n$ there is a prime $q$ dividing exactly one; the involution of Lemma~\ref{lem:sym} negates the product, so the expectation is $0$. If $m = n$, every prime is shared and $f(m)f(n) = \prod_{p\mid m}\varepsilon_p^2 = 1$.
\end{proof}

\noindent Equivalently, with $\chi(m) = \one[m \text{ squarefree}]$, the diagonal reads $\E[f(m)^2] = \chi(m) = \chi(m)^2$, since $\chi \in \{0,1\}$ is idempotent.

\begin{theorem}[Variance equals squarefree count]\label{thm:var}
For any finite set $A \subseteq \N$,
\[
\Var\Big(\sum_{n \in A} f(n)\Big) = \#\{n \in A : n \text{ squarefree}\}.
\]
\end{theorem}
\begin{proof}
Let $S = \sum_{n\in A} f(n)$. The variance is unaffected by the deterministic term $n=1$, so we may take $A \subseteq \{2,3,\dots\}$ and apply Lemma~\ref{lem:mean} to get $\E[S] = 0$. Then
\[
\Var(S) = \E[S^2] = \sum_{m,n\in A}\E[f(m)f(n)] = \sum_{n \in A}\chi(n) = \#\{n \in A : n \text{ squarefree}\},
\]
using Theorem~\ref{thm:orth} to kill off-diagonal terms.
\end{proof}

\begin{corollary}[Short-interval variance]\label{cor:interval}
For real $x \ge 1$ and $y \ge 0$,
\[
\sigma(x,y)^2 = \Var\Big(\sum_{x \le n \le x+y} f(n)\Big) = \#\{n \in [x,x+y] : n \text{ squarefree}\}.
\]
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:var} with $A = \{n \in \Z : x \le n \le x+y\}$.
\end{proof}

\section{The squarefree indicator under the uniform law}
Let $N \ge 1$ and place the uniform law on $\{1,\dots,N\}$, with $\E_N[h] = \frac1N\sum_{m=1}^N h(m)$ and $\Var_N(h) = \E_N[(h - \E_N[h])^2]$. Let $\chi(m) = \one[m\text{ squarefree}]$ and $Q(N) = \#\{m\le N : m\text{ squarefree}\}$.

\begin{lemma}[Variance decomposition]\label{lem:vardecomp}
For any $h$ and $N \ge 1$, $\Var_N(h) = \E_N[h^2] - (\E_N[h])^2$.
\end{lemma}
\begin{proof}
Expand $(h - \E_N[h])^2 = h^2 - 2\E_N[h]\,h + (\E_N[h])^2$ and apply linearity of $\E_N$.
\end{proof}

\begin{theorem}[Squarefree-indicator variance]\label{thm:chi}
With the uniform law on $\{1,\dots,N\}$,
\[
\Var_N(\chi) = \frac{Q(N)}{N} - \Big(\frac{Q(N)}{N}\Big)^2 = q_N(1-q_N), \qquad q_N := \frac{Q(N)}{N}.
\]
\end{theorem}
\begin{proof}
Since $\chi \in \{0,1\}$, it is idempotent: $\chi^2 = \chi$. Hence $\E_N[\chi^2] = \E_N[\chi] = Q(N)/N$, and Lemma~\ref{lem:vardecomp} gives $\Var_N(\chi) = Q(N)/N - Q(N)^2/N^2 = q_N(1-q_N)$.
\end{proof}

\begin{remark}
This is the variance of a Bernoulli variable with success probability $q_N$. As $N\to\infty$, $q_N \to 6/\pi^2$, so $\Var_N(\chi) \to \tfrac{6}{\pi^2}(1-\tfrac{6}{\pi^2}) \approx 0.2383$.
\end{remark}

\section{Asymptotic normalization}

\begin{fact}[Squarefree density in short intervals]\label{fact:density}
As $x \to \infty$, for $y = y(x)$ in the admissible range,
\[
\#\{n \in [x,x+y] : n \text{ squarefree}\} = \frac{6}{\pi^2}\,y + o(y).
\]
This holds unconditionally for $y \gg x^{1/2}$ from $Q(t) = \tfrac{6}{\pi^2}t + O(\sqrt t)$, and, with high probability, for all $y \to \infty$ under the Riemann Hypothesis. Here $6/\pi^2 = 1/\zeta(2)$.
\end{fact}

\begin{corollary}[Normalization]\label{cor:norm}
In the admissible range, $\sigma(x,y)^2 = \#\{n \in [x,x+y]: n \text{ squarefree}\} \sim \tfrac{6}{\pi^2}\,y$.
\end{corollary}
\begin{proof}
Combine Corollary~\ref{cor:interval} with Fact~\ref{fact:density}.
\end{proof}

\begin{remark}[Comparison with Steinhaus]
For Steinhaus, all integers carry nonzero unimodular values and the analogous variance is $y + O(1)$, giving $\sigma_{\mathrm{St}}(x,y)^2 \sim y$. The Rademacher normalization is smaller by exactly the squarefree density $6/\pi^2$ --- the quantitative fingerprint of the choice $f(n)=0$ on non-squarefree $n$.
\end{remark}

\section{The central limit theorem and the moment method}

\begin{conjecture}[Short-interval CLT, Rademacher form]\label{conj:clt}
Let $f$ be a Rademacher random multiplicative function, and let $y = y(x)$ satisfy $y \to \infty$, $y = o(x)$, with $[x,x+y]$ containing $(6/\pi^2)y + o(y)$ squarefree integers with probability $1-o(1)$. Then
\[
\frac{1}{\sigma(x,y)}\sum_{x \le n \le x+y} f(n) \xrightarrow{\ d\ } N(0,1), \qquad \sigma(x,y)^2 \sim \frac{6}{\pi^2}y.
\]
\end{conjecture}

The standard route is the \emph{method of moments}: show all standardized moments converge to those of $N(0,1)$, namely $0$ for odd orders and $(k-1)!! = 1,3,15,105,\dots$ for even orders. Theorems~\ref{thm:var}--\ref{thm:orth} supply the order-$2$ input.

\begin{proposition}[Higher mixed moments]\label{prop:moments}
For $n_1,\dots,n_k \in \N$,
\[
\E[f(n_1)\cdots f(n_k)] = \prod_p \E[\varepsilon_p^{\,a_p}], \qquad a_p = \#\{i : p \mid n_i,\ n_i \text{ squarefree}\},
\]
provided every $n_i$ is squarefree (else the product is $0$). Since $\E[\varepsilon_p^{\,a}] = 1$ if $a$ even and $0$ if $a$ odd, the moment equals $1$ exactly when every prime divides an even number of the $n_i$ --- i.e. when $\{n_1,\dots,n_k\}$ pairs perfectly into equal values --- and is $0$ otherwise.
\end{proposition}
\begin{proof}
Expand the product over primes and use independence across distinct primes: $\E[\prod_p \varepsilon_p^{a_p}] = \prod_p \E[\varepsilon_p^{a_p}]$. Each single-prime average is $1$ or $0$ by parity, since $\varepsilon_p^2 = 1$ and $\E[\varepsilon_p] = 0$.
\end{proof}

\begin{corollary}[Even moments count pairings]
$\E[S^{2r}]$ equals the number of pairings of the $2r$ chosen indices into equal squarefree values. To leading order the dominant contribution is $(2r-1)!!\,\big(\#\{\text{squarefree } n \in A\}\big)^r$, giving standardized fourth moment $\to 3$ and, generally, Gaussian moments $(2r-1)!!$.
\end{corollary}

This isolates what remains: controlling the error between the exact combinatorial moment and its Gaussian leading term. The order-$2$ term is settled here; the fourth moment $\to 3$ is the decisive next milestone.

\section{Algorithms}
\textbf{Algorithm A (squarefree sieve).} Mark multiples of $p^2$ for primes $p \le \sqrt N$ to obtain \texttt{sf[1..N]}; then $Q(N)$ and interval counts are prefix-sum differences. Time $O(N\log\log N)$.

\noindent\textbf{Algorithm B (exact variance by enumeration).} Enumerate all $2^{|P|}$ sign patterns, evaluate $S(\omega)$, and compute the empirical variance; the output equals $\#\{n \in A : n \text{ squarefree}\}$, verifying Theorem~\ref{thm:var}.

\noindent\textbf{Algorithm C (Monte Carlo histogram).} Sample random sign vectors, form $S(x,y)/\sigma(x,y)$ with $\sigma^2$ from Algorithm~A, and histogram against $N(0,1)$.

\section{Discussion}
The exact identity cleanly factors the short-interval CLT into a \emph{probabilistic} piece (orthogonality of moments of $\pm1$ flips, elementary and unconditional) and a \emph{number-theoretic} piece (the count of squarefree integers in $[x,x+y]$, where all analytic difficulty resides). For Steinhaus the second piece is trivial; for Rademacher the density $6/\pi^2$ enters and fixes the admissible range.

\section{Future work}
\begin{enumerate}
\item Establish the squarefree density asymptotic $\tfrac{6}{\pi^2}N + O(\sqrt N)$ and its interval form; feed into Corollary~\ref{cor:interval}.
\item Develop the full mixed-moment calculus of Proposition~\ref{prop:moments}.
\item Prove the fourth moment $\to 3$, a finite-model step toward the CLT.
\item Prove the Steinhaus covariance analogue, where the variance counts all integers.
\end{enumerate}

\end{document}

