"""Exact verification of the variance identity by full enumeration.

For a finite set A of integers, the variance of sum_{n in A} f(n) over a
Rademacher random multiplicative function equals the number of squarefree
integers in A. We check this exactly by averaging over all 2^{|P|} sign
patterns, where P is the set of primes dividing elements of A.
"""
from __future__ import annotations
import itertools
from typing import Dict, Iterable, List, Sequence


def prime_factors(n: int) -> List[int]:
    factors: List[int] = []
    d, m = 2, n
    while d * d <= m:
        if m % d == 0:
            factors.append(d)
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors.append(m)
    return factors


def is_squarefree(n: int) -> bool:
    if n < 1:
        return False
    m, d = n, 2
    while d * d <= m:
        if m % (d * d) == 0:
            return False
        if m % d == 0:
            m //= d
        else:
            d += 1 if d == 2 else 2
    return True


def f_value(n: int, signs: Dict[int, int]) -> int:
    if not is_squarefree(n):
        return 0
    prod = 1
    for p in prime_factors(n):
        prod *= signs[p]
    return prod


def primes_dividing(numbers: Iterable[int]) -> List[int]:
    ps: set[int] = set()
    for n in numbers:
        ps.update(prime_factors(n))
    return sorted(ps)


def exact_variance(A: Sequence[int]) -> float:
    P = primes_dividing(A)
    total = total_sq = 0.0
    count = 0
    for pattern in itertools.product((-1, 1), repeat=len(P)):
        signs = dict(zip(P, pattern))
        s = sum(f_value(n, signs) for n in A)
        total += s
        total_sq += s * s
        count += 1
    mean = total / count
    return total_sq / count - mean * mean


if __name__ == "__main__":
    for (a, b) in [(2, 12), (8, 24), (20, 36), (30, 46)]:
        A = list(range(a, b + 1))
        var = exact_variance(A)
        sf = sum(1 for n in A if is_squarefree(n))
        print(f"A=[{a},{b}] Var={var:.4f} squarefree={sf} match={abs(var-sf)<1e-9}")

