function SquarefreeSieve(N):
    sf[0..N] <- all True; sf[0] <- False
    d <- 2
    while d*d <= N:
        for k in d*d, 2*d*d, ... <= N: sf[k] <- False
        d <- d + 1
    return sf

function SquarefreeCount(a, b):
    sf <- SquarefreeSieve(b)
    return sum of sf[n] for n in a..b

